"1611 :     private Dfp multiplyFast(final int x) {
1612 :         Dfp result = newInstance(this);
1613 : 
1614 :         /* handle special cases */
1615 :         if (nans != FINITE) {
1616 :             if (isNaN()) {
1617 :                 return this;
1618 :             }
1619 : 
1620 :             if (nans == INFINITE && x != 0) {
1621 :                 result = newInstance(this);
1622 :                 return result;
1623 :             }
1624 : 
1625 :             if (nans == INFINITE && x == 0) {
1626 :                 field.setIEEEFlagsBits(DfpField.FLAG_INVALID);
1627 :                 result = newInstance(getZero());
1628 :                 result.nans = QNAN;
1629 :                 result = dotrap(DfpField.FLAG_INVALID, MULTIPLY_TRAP, newInstance(getZero()), result);
1630 :                 return result;
1631 :             }
1632 :         }
1633 : 
1634 :         /* range check x */
1635 :         if (x < 0 || x >= RADIX) {
1636 :             field.setIEEEFlagsBits(DfpField.FLAG_INVALID);
1637 :             result = newInstance(getZero());
1638 :             result.nans = QNAN;
1639 :             result = dotrap(DfpField.FLAG_INVALID, MULTIPLY_TRAP, result, result);
1640 :             return result;
1641 :         }
1642 : 
1643 :         int rh = 0;
1644 :         for (int i = 0; i < mant.length; i++) {
1645 :             final int r = mant[i] * x + rh;
1646 :             rh = r / RADIX;
1647 :             result.mant[i] = r - rh * RADIX;
1648 :         }
1649 : 
1650 :         int lostdigit = 0;
1651 :         if (rh != 0) {
1652 :             lostdigit = result.mant[0];
1653 :             result.shiftRight();
1654 :             result.mant[mant.length-1] = rh;
1655 :         }
1656 : 
1657 :         if (result.mant[mant.length-1] == 0) { // if result is zero, set exp to zero
1658 :             result.exp = 0;
1659 :         }
1660 : 
1661 :         final int excp = result.round(lostdigit);
1662 :         if (excp != 0) {
1663 :             result = dotrap(excp, MULTIPLY_TRAP, result, result);
1664 :         }
1665 : 
1666 :         return result;
1667 :     }"

"191 :     private DfpField(final int decimalDigits, final boolean computeConstants) {
192 : 
193 :         this.radixDigits = (decimalDigits < 13) ? 4 : (decimalDigits + 3) / 4;
194 :         this.rMode       = RoundingMode.ROUND_HALF_EVEN;
195 :         this.ieeeFlags   = 0;
196 :         this.zero        = new Dfp(this, 0);
197 :         this.one         = new Dfp(this, 1);
198 :         this.two         = new Dfp(this, 2);
199 : 
200 :         if (computeConstants) {
201 :             // set up transcendental constants
202 :             synchronized (DfpField.class) {
203 : 
204 :                 // as a heuristic to circumvent Table-Maker's Dilemma, we set the string
205 :                 // representation of the constants to be at least 3 times larger than the
206 :                 // number of decimal digits, also as an attempt to really compute these
207 :                 // constants only once, we set a minimum number of digits
208 :                 computeStringConstants((decimalDigits < 67) ? 200 : (3 * decimalDigits));
209 : 
210 :                 // set up the constants at current field accuracy
211 :                 sqr2           = new Dfp(this, sqr2String);
212 :                 sqr2Split      = split(sqr2String);
213 :                 sqr2Reciprocal = new Dfp(this, sqr2ReciprocalString);
214 :                 sqr3           = new Dfp(this, sqr3String);
215 :                 sqr3Reciprocal = new Dfp(this, sqr3ReciprocalString);
216 :                 pi             = new Dfp(this, piString);
217 :                 piSplit        = split(piString);
218 :                 e              = new Dfp(this, eString);
219 :                 eSplit         = split(eString);
220 :                 ln2            = new Dfp(this, ln2String);
221 :                 ln2Split       = split(ln2String);
222 :                 ln5            = new Dfp(this, ln5String);
223 :                 ln5Split       = split(ln5String);
224 :                 ln10           = new Dfp(this, ln10String);
225 : 
226 :             }
227 :         } else {
228 :             // dummy settings for unused constants
229 :             sqr2           = null;
230 :             sqr2Split      = null;
231 :             sqr2Reciprocal = null;
232 :             sqr3           = null;
233 :             sqr3Reciprocal = null;
234 :             pi             = null;
235 :             piSplit        = null;
236 :             e              = null;
237 :             eSplit         = null;
238 :             ln2            = null;
239 :             ln2Split       = null;
240 :             ln5            = null;
241 :             ln5Split       = null;
242 :             ln10           = null;
243 :         }
244 : 
245 :     }"

